/// Another player as a native mod reads it (Arsenal's patch).
#[allow(dead_code)]
#[derive(Clone, Debug)]
pub(crate) struct NativeOther {
    pub(crate) id: u32,
    /// The player's account id (0 when unknown).
    pub(crate) uuid: u128,
    pub(crate) name: String,
    pub(crate) x: f64,
    pub(crate) y: f64,
    pub(crate) z: f64,
    pub(crate) health: f32,
    pub(crate) absorption: f32,
    pub(crate) hurt_time: i32,
    /// Ticks they've been using an item (eating, drinking, drawing a bow), 0 when not; and whether it's the off hand's.
    pub(crate) using: i32,
    pub(crate) using_off_hand: bool,
    /// Main hand, off hand, feet, legs, chest, head (`EquipmentSlot` order).
    pub(crate) equipment: Vec<Option<ItemStack>>,
}

/// Entity events the server sent since a native mod last read them: (entity id, event) (Arsenal's patch).
pub(crate) static ARSENAL_ENTITY_EVENTS: std::sync::Mutex<Vec<(u32, i32)>> = std::sync::Mutex::new(Vec::new());

/// Keeps an entity event for native mods (Arsenal's patch); the oldest go past 500.
pub(crate) fn arsenal_entity_event(id: u32, event: i32) {
    if let Ok(mut events) = ARSENAL_ENTITY_EVENTS.lock() {
        events.push((id, event));
        if events.len() > 500 {
            events.remove(0);
        }
    }
}

/// The other players in the world this window shows (Arsenal's patch).
pub(super) fn arsenal_others(&self) -> Vec<NativeOther> {
    self.remote_player_names()
        .into_iter()
        .filter_map(|(id, name)| {
            let m = self.mobs.iter().find(|m| m.id == id)?;
            Some(NativeOther {
                id,
                uuid: self.remote_player_uuid(id).unwrap_or(0),
                name,
                x: m.position.x as f64,
                y: m.position.y as f64,
                z: m.position.z as f64,
                health: m.health,
                absorption: m.absorption,
                hurt_time: m.hurt_time,
                using: m.extra.using_item,
                using_off_hand: m.extra.using_off_hand,
                equipment: m.equipment_stacks().into_iter().take(6).collect(),
            })
        })
        .collect()
}
/// The entity events since the last call, oldest first (Arsenal's patch).
pub(super) fn arsenal_entity_events(&self) -> Vec<(u32, i32)> {
    ARSENAL_ENTITY_EVENTS.lock().map(|mut e| std::mem::take(&mut *e)).unwrap_or_default()
}
